using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
namespace Dafeiyu.Tests
{
    public static class DraftConversationTests
    {
        static int passed,failed;static string root;static readonly BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;
        static void Check(bool ok,string text){if(!ok)throw new Exception(text);}
        static void Run(string name,Action action){try{action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
        static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var x in All<T>(VisualTreeHelper.GetChild(root,i)))yield return x;}
        static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(40)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
        static PetWindow Pet(string existing=null){var s=new PetSettings{AgentEnabled=false,ReadReplies=false,GreetingEnabled=false,AutoUpdate=false,OnboardingState="completed"};s.Text.BaseUrl="http://127.0.0.1:1";s.Text.Model="fixture";foreach(var key in s.Hotkeys.Keys.ToArray())s.Hotkeys[key]="";var p=new PetWindow(null,s,new SettingsStore(Path.Combine(existing??Path.Combine(root,Guid.NewGuid().ToString("N")),"settings.json")),null);typeof(PetWindow).GetField("workspaces",hidden).SetValue(p,new ConversationWorkspaceManager(p.Store.DirectoryPath,p.Skin.Id,()=>new Api(),()=>new Silent(),()=>null,()=>s,()=>true));return p;}
        static int Count(PetWindow p){return p.Projects.Projects.Sum(x=>x.Conversations.Count)+p.Projects.UnassignedConversations.Count+p.Projects.QuickConversations.Count;}
        static ChatWindow Chat(){return Application.Current.Windows.OfType<ChatWindow>().Single();}
        static void Send(ChatWindow chat){All<MarkdownEditor>(chat).Single(t=>t.Name=="MessageInput").Text="draft input";All<Button>(chat).Single(b=>b.Name=="SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<15;i++)Pump();}
        [STAThread]public static int Main(){root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"drafts-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Run("new draft survives window close and application recreation",DurableDraft);Run("project selection saves and restores the matching persistent draft scope",ProjectDraftScope);Run("quick opening stays unlisted until accepted submission",QuickSubmission);Run("failed quick submission retains input without creating a list entry",QuickFailure);Run("saved conversation drafts and pending new draft survive switching",SwitchingDrafts);Run("expanding quick chat shares its unsent draft without listing it",QuickExpansion);Run("new conversation stays unlisted until first successful send",PendingDraft);Run("failed submission retains draft without adding a catalog entry",FailedSubmission);Run("project choice is pending until send and then persists under that project",ProjectChoice);Run("unassigned conversation appears in recent and can move into a project",Unassigned);Run("recent project visibility toggle persists without hiding unassigned chats",RecentFilter);app.Shutdown();Console.WriteLine("Draft conversation tests: "+passed+" passed, "+failed+" failed");return failed==0?0:1;}
        static void ProjectDraftScope(){var p=Pet();string data=p.Store.DirectoryPath;string projectId;try{p.Settings.AgentEnabled=true;var project=ProjectCatalogStore.CreateProject(p.Projects,"draft target",root);projectId=project.Id;p.ProjectStore.Save(p.Projects);p.NewActiveConversation();Pump();var input=All<MarkdownEditor>(Chat()).Single(x=>x.Name=="MessageInput");input.Text="unassigned text";var workspace=p.Workspaces.OpenWorkspaces.Single(x=>x.IsDraft);workspace.FollowProject(project);Pump();Check(input.Text=="","project picker must restore the target scope rather than retain unassigned text");input.Text="project text";Chat().Close();for(int i=0;i<100&&p.Workspaces.OpenCount>0;i++)Pump();}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();p.Close();Pump();}
var restored=Pet(data);try{restored.Settings.AgentEnabled=true;restored.NewProjectConversation(restored.Projects.Projects.Single(x=>x.Id==projectId));Pump();Check(All<MarkdownEditor>(Chat()).Single(x=>x.Name=="MessageInput").Text=="project text","project draft restored under the wrong project");restored.NewActiveConversation();Pump();Check(All<MarkdownEditor>(Chat()).Single(x=>x.Name=="MessageInput").Text=="unassigned text","project selection overwrote the prior unassigned draft");}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();restored.Close();Pump();}}
        static void DurableDraft(){var p=Pet();string directory=p.Store.DirectoryPath;string value="重启后保留\nunsent draft";try{int before=Count(p);p.NewActiveConversation();Pump();All<MarkdownEditor>(Chat()).Single(x=>x.Name=="MessageInput").Text=value;Chat().Close();for(int i=0;i<100&&p.Workspaces.OpenCount>0;i++)Pump();p.NewActiveConversation();Pump();Check(All<MarkdownEditor>(Chat()).Single(x=>x.Name=="MessageInput").Text==value,"window close lost draft");Check(Count(p)==before,"unsent draft created history row");Chat().Close();for(int i=0;i<100&&p.Workspaces.OpenCount>0;i++)Pump();}finally{p.Close();Pump();}
var restored=Pet(directory);try{restored.NewActiveConversation();Pump();var input=All<MarkdownEditor>(Chat()).Single(x=>x.Name=="MessageInput");Check(input.Text==value,"application recreation lost draft");restored.Settings.Text.BaseUrl="invalid-url";All<Button>(Chat()).Single(x=>x.Name=="SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(input.Text==value,"failed submission lost durable draft");restored.Settings.Text.BaseUrl="http://127.0.0.1:1";All<Button>(Chat()).Single(x=>x.Name=="SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<15;i++)Pump();restored.NewActiveConversation();Pump();Check(All<MarkdownEditor>(Chat()).Single(x=>x.Name=="MessageInput").Text=="","accepted submission resurrected old new-chat draft");}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();restored.Close();Pump();}}
        static void QuickSubmission(){var p=Pet();try{int before=Count(p);p.ShowQuickChat();Pump();Check(Count(p)==before,"opening quick chat created an empty catalog row");var quick=Application.Current.Windows.OfType<QuickChatWindow>().Single();var input=All<MarkdownEditor>(quick).Single(t=>t.Name=="QuickMessageInput");input.Text="unsent quick draft";Check(Count(p)==before,"typing quick draft created a catalog row");All<Button>(quick).Single(b=>b.Name=="SendQuickMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<15;i++)Pump();Check(Count(p)==before+1&&p.Projects.QuickConversations.Count==1,"quick send did not register exactly one quick conversation");Check(p.ProjectStore.Load().QuickConversations.Count==1,"accepted quick conversation was not saved");quick.Close();Pump();p.ShowQuickChat();Pump();Check(Count(p)==before+1,"reopening quick chat created another empty row");}finally{foreach(var w in Application.Current.Windows.OfType<QuickChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void QuickFailure(){var p=Pet();try{p.ShowQuickChat();Pump();int before=Count(p);p.Settings.Text.BaseUrl="invalid-url";var quick=Application.Current.Windows.OfType<QuickChatWindow>().Single();var input=All<MarkdownEditor>(quick).Single(t=>t.Name=="QuickMessageInput");input.Text="keep quick draft";All<Button>(quick).Single(b=>b.Name=="SendQuickMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(Count(p)==before&&input.Text=="keep quick draft","failed quick submit added a catalog row or lost input");}finally{foreach(var w in Application.Current.Windows.OfType<QuickChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void SwitchingDrafts(){var p=Pet();try{var owner=ProjectCatalogStore.UnassignedProject(p.Projects,p.Settings);var a=ProjectCatalogStore.CreateConversation(p.Projects,owner.Id,"A");var b=ProjectCatalogStore.CreateConversation(p.Projects,owner.Id,"B");foreach(var c in new[]{a,b}){c.Mode="chat";c.PetId=p.Skin.Id;}p.NewActiveConversation();Pump();var chat=Chat();var input=All<MarkdownEditor>(chat).Single(t=>t.Name=="MessageInput");string pending=chat.ConversationId;input.Text="new draft 中文\nsecond line";p.OpenProjectConversation(owner,a);Pump();input.Text="A unsent 中文";p.OpenProjectConversation(owner,b);Pump();Check(input.Text=="","A input leaked into B");input.Text="B unsent";p.OpenProjectConversation(owner,a);Pump();Check(input.Text=="A unsent 中文","A draft was not restored");p.OpenProjectConversation(owner,b);Pump();Check(input.Text=="B unsent","B draft was not restored");int before=Count(p);p.NewActiveConversation();Pump();Check(chat.ConversationId==pending&&input.Text=="new draft 中文\nsecond line","new conversation button discarded the pending draft");Check(Count(p)==before,"returning to pending draft created a catalog row");p.NewActiveConversation();Pump();Check(chat.ConversationId==pending,"repeated new action allocates another pending workspace");All<Button>(chat).Single(x=>x.Name=="SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));for(int i=0;i<15;i++)Pump();Check(Count(p)==before+1&&input.Text=="","sending draft did not register once and clear input");p.NewActiveConversation();Pump();Check(chat.ConversationId!=pending&&input.Text=="","after sending, new conversation reuses stale text");p.OpenProjectConversation(owner,a);Pump();Check(input.Text=="A unsent 中文","sending another draft cleared A input");}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void PendingDraft(){var p=Pet();try{int count=Count(p);p.NewActiveConversation();Pump();Check(Count(p)==count,"new conversation was saved before sending");var chat=Chat();Check(!All<Button>(chat).Any(b=>b.Name=="ConversationProjectPicker"),"ordinary chat exposed project selection");chat.Close();Pump();Check(Count(p)==count,"closing empty draft created a saved chat");}finally{p.Close();Pump();}}
        static void QuickExpansion(){var p=Pet();try{p.ShowQuickChat();Pump();var quick=Application.Current.Windows.OfType<QuickChatWindow>().Single();var quickInput=All<MarkdownEditor>(quick).Single(t=>t.Name=="QuickMessageInput");quickInput.Text="expand unsent 中文 /";int before=Count(p);p.ShowChat();Pump();var chat=Chat();var input=All<MarkdownEditor>(chat).Single(t=>t.Name=="MessageInput");Check(input.Text=="expand unsent 中文 /"&&Count(p)==before,"expanding quick chat lost the draft or saved an empty row");input.Text="full window draft";p.ShowQuickChat();Pump();Check(quickInput.Text=="full window draft","quick and full views do not share the same conversation draft");}finally{foreach(var w in Application.Current.Windows.OfType<QuickChatWindow>().ToArray())w.Close();foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void FailedSubmission(){var p=Pet();try{p.NewActiveConversation();Pump();int before=Count(p);p.Settings.Text.BaseUrl="invalid-url";var chat=Chat();var input=All<MarkdownEditor>(chat).Single(t=>t.Name=="MessageInput");input.Text="retain this draft";All<Button>(chat).Single(b=>b.Name=="SendMessage").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(Count(p)==before&&input.Text=="retain this draft","failed submission saved an empty conversation or lost the draft");}finally{foreach(var chat in Application.Current.Windows.OfType<ChatWindow>().ToArray())chat.Close();p.Close();Pump();}}
        static void ProjectChoice(){var p=Pet();try{var project=ProjectCatalogStore.CreateProject(p.Projects,"chosen",root);int count=project.Conversations.Count;p.NewProjectConversation(project);Pump();Check(project.Conversations.Count==count,"choosing a project eagerly saved an empty chat");Send(Chat());Check(project.Conversations.Count==count+1,"first send did not add chat to selected project");var saved=p.ProjectStore.Load();Check(saved.Projects.Single(x=>x.Id==project.Id).Conversations.Count==count+1,"project membership not persisted");}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void Unassigned(){var p=Pet();try{p.Settings.AgentEnabled=true;var project=ProjectCatalogStore.CreateProject(p.Projects,"target",root);p.NewActiveConversation();Pump();Send(Chat());Check(p.Projects.UnassignedConversations.Count==1,"unassigned chat was not saved independently");var c=p.Projects.UnassignedConversations[0];Check(p.MoveConversation(ProjectCatalogStore.UnassignedProject(p.Projects,p.Settings),project,c),"moving unassigned chat failed");Check(!p.Projects.UnassignedConversations.Any()&&project.Conversations.Any(x=>x.Id==c.Id),"unassigned drag changed or lost chat identity");var workspace=p.Workspaces.OpenWorkspaces.Single(x=>x.Id==c.Id);Check(workspace.Session.History.Messages.Any(x=>x.Content=="draft input"),"move lost conversation history");}finally{foreach(var w in Application.Current.Windows.OfType<ChatWindow>().ToArray())w.Close();p.Close();Pump();}}
        static void RecentFilter(){var catalog=new ProjectCatalog();var project=ProjectCatalogStore.CreateProject(catalog,"project",root);catalog.UnassignedConversations.Add(new ConversationDefinition{Id="unassignedtest",Name="Loose"});var sidebar=new ProjectSidebar(new ProjectCatalogStore(Path.Combine(root,"recent.json")),catalog,delegate{},delegate{},delegate{},delegate{},delegate{});var toggle=All<Button>(sidebar).Single(b=>b.Name=="ToggleSection_recent");Check(toggle.ContextMenu!=null&&toggle.ContextMenu.Items.OfType<MenuItem>().Any(m=>m.Name=="NewSidebarSection"),"recent group omits section actions");toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!All<Button>(sidebar).Any(b=>b.Name.StartsWith("RecentConversation_")),"recent group did not collapse");All<Button>(sidebar).Single(b=>b.Name=="ToggleSection_recent").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(All<Button>(sidebar).Any(b=>b.Name=="RecentConversation_unassignedtest")&&All<Button>(sidebar).Any(b=>b.Name=="RecentConversation_"+project.Conversations[0].Id),"recent expansion lost shared work records");}
        sealed class Api:IConversationApi{public Task<string> ChatAsync(ConnectionSettings s,IList<ChatMessage> m,CancellationToken t){return Task.FromResult("reply");}public Task<string> TranscribeAsync(ConnectionSettings s,byte[] b,CancellationToken t){return Task.FromResult("");}public Task<byte[]> SpeechAsync(ConnectionSettings s,string v,string text,CancellationToken t){return Task.FromResult(new byte[0]);}public void Dispose(){}}
        sealed class Silent:IReplySpeech{public Task SpeakAsync(string s,PetSettings p,CancellationToken t){return Task.FromResult(0);}public void Stop(){}public void SetVolume(int n){}public void Dispose(){}}
    }
}
